style.css:
@-moz-document domain("gemini.google.com") {
/* 1. Reset complet pentru containerul principal al codului */
    main pre,
    main code,
    div[class*="code-block"],
    div:has(pre) {
        background: #f8f9fa !important;
        background-color: #f8f9fa !important;
        background-image: none !important;
        color: #202124 !important;
        border: 1px solid #dadce0 !important;
    }

    /* 2. Bara de sus (unde scrie PHP, Java, etc. și sunt butoanele) */
    main pre div,
    div:has(pre) > div:first-child,
    div[class*="code-block"] > div:first-child {
        background: #f1f3f4 !important;
        background-color: #f1f3f4 !important;
        color: #3c4043 !important;
        border-bottom: 1px solid #dadce0 !important;
    }

    /* 3. Butoanele de copy/download din bara de sus */
    main pre button, 
    main pre svg,
    div:has(pre) button,
    div:has(pre) svg {
        color: #5f6368 !important;
        fill: #5f6368 !important;
    }

    /* --- 4. Corecție culori Syntax Highlighting (Tema Light) --- */
    
    /* Cuvinte cheie / Structuri de control */
    span[class*="keyword"], .token.keyword {
        color: #d73a49 !important;
        font-weight: bold !important;
    }

    /* Variabile */
    span[class*="variable"], .token.variable {
        color: #005cc5 !important;
    }

    /* String-uri / Text între ghilimele */
    span[class*="string"], .token.string {
        color: #032f62 !important;
    }

    /* Funcții */
    span[class*="function"], .token.function {
        color: #6f42c1 !important;
    }

    /* Comentarii */
    span[class*="comment"], .token.comment {
        color: #6a737d !important;
        font-style: italic !important;
    }

    /* Numere, Operatori, Booleeni */
    span[class*="number"], .token.number,
    span[class*="operator"], .token.operator,
    span[class*="boolean"], .token.boolean {
        color: #d73a49 !important;
    }
}
